async ({ shell: { exec } }) => {
  const script = `mkdir -p /tmp/threads; for r in $(git for-each-ref refs/pi/threads --format='%(refname:short)' | sed 's#pi/threads/##'); do out=/tmp/threads/$r.jsonl; : > $out; for c in $(git rev-list --reverse refs/pi/threads/$r); do git show $c:batch.json >> $out; echo >> $out; done; done; wc -l /tmp/threads/*.jsonl | tail -20; du -sh /tmp/threads`;
  const s = await exec(script, { timeoutMs: 28000 });
  return s.stdout + s.stderr;
}
